<script setup lang="ts">
import {uiError,uiErrorMessage} from '../module-localization.ts';
import {uiMessage,joinMessages} from '../module-localization.ts';
import {tr,messageRef} from '../../i18n/index.ts';
import {useWebSettings,settingsFields} from '../../state/web-settings.ts';
import ResearchUpload from '../../components/ResearchUpload.vue';
import {syncNumberInput} from '../../design/numeric-input.ts';
import AppIcon from '../../components/AppIcon.vue';
import {vTimePrecision} from '../../design/time-precision.ts';
import {ref,computed,onMounted,onUnmounted,markRaw,watch} from 'vue';
import type {ResearchContext,ResearchFile,DirectoryGrant,ParameterTable,SpectrogramView} from '../../platform/research.ts';
import {researchAudio} from '../../platform/research.ts';
import {workspace,host} from '../../state/workspace.ts';
import {stop} from '../../state/audio.ts';
import {preferences} from '../../state/fonts.ts';
import {lipParameterTable} from './lip.ts';
import WaveformViewport from '../../components/WaveformViewport.vue';
import ModuleFrame from '../../components/ModuleFrame.vue';
import ModuleToolbar from '../../components/ModuleToolbar.vue';
import ModuleWorkbench from '../../components/ModuleWorkbench.vue';
import ParameterFigure from './ParameterFigure.vue';
import {plotGroupTitle,matchingTable,visibleParameters,setGroupParameters,removeGroup,deleteGroup,annotationRuns,type PlotGroup} from './state.ts';
const props=defineProps<{context:ResearchContext;stateKey:string;active:boolean}>();
const emit=defineEmits<{references:[];help:[];close:[]}>();
const waveformArea=ref<HTMLElement>();
const fontScale=computed(()=>preferences.value.figure.size/12);
// Reserve both axes for every track, including groups currently using one axis.
const timeAxisInsets=computed(()=>({left:76*fontScale.value,right:76*fontScale.value}));
const wave=workspace(props.stateKey),files=ref<ResearchFile[]>([]),audioDir=ref<DirectoryGrant>(),tableDir=ref<DirectoryGrant>();
const offsetInput=computed({get:()=>wave.offset,set:(value:number|string)=>{if(wave.asset)wave.offset=Math.max(0,Math.min(wave.asset.duration-wave.asset.duration/wave.zoom,Number(value)||0));}});
const durationInput=computed({get:()=>wave.asset?wave.asset.duration/wave.zoom:0,set:(value:number|string)=>{if(!wave.asset)return;wave.zoom=wave.asset.duration/Math.max(.01,Math.min(wave.asset.duration,Number(value)||wave.asset.duration));wave.offset=Math.min(wave.offset,wave.asset.duration-wave.asset.duration/wave.zoom);}});
const recursive=ref(false),previewNote=ref('');
let previewAbort=new AbortController();
const selected=ref(''),tableId=ref(''),table=ref<ParameterTable>(),busy=ref(false),error=messageRef(''),filter=ref(''),search=ref('');
const reaper=ref(true),correction=ref(false),maximized=ref<number|null>(null);
const saved=host.projects.read<{groups?:PlotGroup[]}>('m02.'+props.stateKey,{});
const groups=ref<PlotGroup[]>(Array.isArray(saved.groups)&&saved.groups.every(g=>Number.isInteger(g.id)&&typeof g.title==='string'&&Array.isArray(g.parameters)&&g.parameters.every(p=>typeof p==='string'))?saved.groups:[{id:1,title:'图窗 1',parameters:[]}]);
const target=ref(groups.value[0]?.id??0);
const currentGroup=computed(()=>groups.value.find(group=>group.id===target.value));
const marked=computed({get:()=>currentGroup.value?.parameters??[],set:(parameters:string[])=>{groups.value=setGroupParameters(groups.value,target.value,parameters);}});
watch(()=>groups.value.map(group=>group.id).join(','),()=>{if(!currentGroup.value)target.value=groups.value[0]?.id??0;});
function selectGroup(id:number){target.value=id;if(maximized.value!==null)maximized.value=id;}
let generation=0,disposed=false;const picker=ref<HTMLInputElement>();
const audios=computed(()=>files.value.filter(f=>f.kind==='audio'));
const current=computed(()=>audios.value.find(f=>f.id===selected.value));
const names=computed(()=>table.value?.columns.filter(name=>!['Time_s','Source_Time_s'].includes(name))??[]);
const visible=computed(()=>visibleParameters(names.value,search.value,reaper.value,correction.value));
const selectedTiers=computed(()=>[...new Set(groups.value.flatMap(g=>g.parameters))].filter(name=>table.value?.kinds[table.value.columns.indexOf(name)]==='text'));
const specLoader=computed(()=>{const file=current.value;return file&&props.context.files.spectrogram?(view:SpectrogramView)=>props.context.files.spectrogram!(file,view):undefined;});
const readingView=ref(false),viewReady=ref(false);let viewTimer:ReturnType<typeof setTimeout>|undefined,viewTicket=0,viewAgain=false;
function scheduleView(){viewReady.value=false;viewTicket++;clearTimeout(viewTimer);viewTimer=setTimeout(()=>void readView(),120);}
async function readView(){
 if(disposed||!table.value?.streamed||!props.context.files.parameters)return;
 if(readingView.value){viewAgain=true;return;}
 const file=files.value.find(f=>f.id===tableId.value);if(!file)return;
 const ticket=viewTicket,loaded=generation,duration=table.value.duration_s??wave.asset?.duration??0;
 const start=Math.max(0,Math.min(wave.offset,duration-.001)),end=Math.min(duration,start+(wave.asset?.duration??duration)/wave.zoom);
 if(!(end>start))return;
 readingView.value=true;
 try{const result=await props.context.files.parameters(file,{start,end,width:1200,parameters:[...new Set(groups.value.flatMap(g=>g.parameters))]});
  if(!disposed&&ticket===viewTicket&&loaded===generation&&file.id===tableId.value){table.value=markRaw(result);viewReady.value=true;error.value='';}
 }catch(e){if(ticket===viewTicket&&loaded===generation)error.value=e instanceof Error?uiErrorMessage(e):uiMessage('modules.parameter-display.failed_to_read_parameter_window');}
 finally{readingView.value=false;if(viewAgain&&!disposed){viewAgain=false;scheduleView();}}
}
watch([()=>tableId.value,()=>table.value?.streamed,()=>wave.offset,()=>wave.zoom,()=>groups.value.map(g=>g.parameters.join('|')).join(';')],scheduleView);
watch(groups,()=>wave.dirty=true,{deep:true});
function save(){const ok=host.projects.write('m02.'+props.stateKey,{groups:groups.value});if(ok)wave.dirty=false;else error.value=uiMessage('modules.parameter-display.failed_to_save_plot_configuration');return ok;}
defineExpose({save});
async function refresh(){busy.value=true;error.value='';try{const first=await props.context.files.list(audioDir.value?.id,recursive.value);const second=tableDir.value?await props.context.files.list(tableDir.value.id,recursive.value):[];if(disposed)return;files.value=[...new Map([...first,...second].map(f=>[f.id,f])).values()];if(selected.value)await loadAudio(selected.value);}catch(e){error.value=e instanceof Error?uiErrorMessage(e):uiMessage('modules.parameter-display.failed_to_read_folder');}finally{busy.value=false;}}
async function choose(kind:'input'|'association'){try{const grant=await props.context.files.choose?.(kind);if(!grant)return;if(kind==='input'){audioDir.value=grant;tableDir.value=undefined;}else tableDir.value=grant;await refresh();}catch(e){error.value=uiErrorMessage(e);}}
async function loadTable(id:string){const ticket=++generation;tableId.value=id;table.value=undefined;if(!id){busy.value=false;return;}busy.value=true;error.value='';try{const file=files.value.find(f=>f.id===id);if(!file)throw uiError(uiMessage('modules.parameter-display.parameter_resource_is_unavailable'));const isLip=file.kind==='lip'||file.kind==='lip_pickle';if(!isLip&&!props.context.files.parameters)throw uiError(uiMessage('modules.parameter-display.parameter_reading_requires_the_local_desktop_app_or_a'));const result=isLip?await lipParameterTable(props.context.files,file):await props.context.files.parameters!(file);if(disposed||ticket!==generation)return;table.value=markRaw(result);const allowed=result.columns.filter(n=>!['Time_s','Source_Time_s'].includes(n));const next=groups.value.map(g=>({...g,parameters:g.parameters.filter(p=>allowed.includes(p))}));if(JSON.stringify(next)!==JSON.stringify(groups.value))groups.value=next;if(!groups.value.some(g=>g.id===target.value))target.value=groups.value[0]?.id??0;}catch(e){if(ticket===generation)error.value=e instanceof Error?uiErrorMessage(e):uiMessage('modules.parameter-display.failed_to_read_parameters');}finally{if(ticket===generation)busy.value=false;}}
async function loadAudio(id:string){previewAbort.abort();previewAbort=new AbortController();previewNote.value='';stop();const ticket=++generation;selected.value=id;wave.asset=null;table.value=undefined;tableId.value='';error.value='';const file=files.value.find(f=>f.id===id);if(!file){busy.value=false;return;}busy.value=true;try{const {asset,previewNote:note}=await researchAudio(props.context.files,file,previewAbort.signal);if(disposed||ticket!==generation)return;previewNote.value=note;wave.asset=markRaw(asset);wave.start=0;wave.end=asset.duration;wave.offset=0;wave.zoom=1;wave.channel=0;const associated=await props.context.files.associatedParameters?.(file);if(disposed||ticket!==generation)return;if(associated&&!files.value.some(f=>f.id===associated.id))files.value.push(associated);const match=associated??matchingTable(file,files.value);await loadTable(match?.id??'');}catch(e){if(ticket===generation)error.value=uiErrorMessage(e);}finally{if(!disposed&&ticket===generation)busy.value=false;}}
function addGroup(){const id=Math.max(0,...groups.value.map(g=>g.id))+1;groups.value.push({id,title:'图窗 '+id,parameters:[]});selectGroup(id);}
function remove(id:number){groups.value=removeGroup(groups.value,id);if(!groups.value.some(g=>g.id===target.value))target.value=groups.value[0]?.id??0;maximized.value=null;}
function deletePlot(id:number){groups.value=deleteGroup(groups.value,id);if(!groups.value.some(g=>g.id===target.value))target.value=groups.value[0]?.id??0;if(maximized.value===id)maximized.value=null;}
function markVisible(){marked.value=[...new Set([...marked.value,...visible.value])];}
function addFiles(event:Event){props.context.files.add?.([...((event.target as HTMLInputElement).files??[])]);void refresh();}
onMounted(()=>{if(props.context.files.kind!=='desktop')void refresh();});onUnmounted(()=>{disposed=true;generation++;viewTicket++;clearTimeout(viewTimer);previewAbort.abort();stop();});
useWebSettings(props.stateKey,{groups,reaper,correction,recursive,...settingsFields(wave,['showBoth','showSpectrogram'])},undefined,()=>wave.dirty=false);
</script>
<template><ModuleFrame unified fit :label="tr('modules.parameter-display.parameter_display_workspace')" class="m02-page">
<template #toolbar><ModuleToolbar :label="tr('modules.parameter-display.parameter_display_actions')"><ResearchUpload :files="context.files" accept=".wav,.xlsx,.ptb.sqlite,.ptb.sqlite3,.lip.json" @uploaded="refresh"/><template v-if="context.files.choose"><button class="primary" @click="choose('input')" :disabled="busy"><AppIcon name="folder"/>{{tr('modules.parameter-display.open_audio_folder')}}</button><small>{{audioDir?.label}}</small><button @click="choose('association')" :disabled="busy">{{tr('modules.parameter-display.select_parameter_folder')}}</button><small>{{tableDir?.label??tr('modules.parameter-display.audio_folder')}}</small></template><template v-else-if="context.files.add"><input ref="picker" type="file" accept=".wav,.xlsx,.ptb.sqlite,.ptb.sqlite3,.lip.json" multiple hidden @change="addFiles"/><button class="primary" @click="picker?.click()">{{tr('modules.parameter-display.add_files')}}</button></template><span v-else>{{tr('modules.parameter-display.audio_and_parameter_tables_in_the_current_file_group')}}</span><label v-if="context.files.choose" class="recursive-option"><input v-model="recursive" type="checkbox" :disabled="busy" @change="refresh"/>{{tr('modules.parameter-display.include_subfolders')}}</label><button @click="refresh" :disabled="busy">{{tr('modules.parameter-display.refresh_files')}}</button><template #actions><button @click="save">{{tr('modules.parameter-display.save_plot_configuration')}}</button><button type="button" data-action="module-help" @click="emit('help')">{{tr('modules.parameter-display.help')}}</button><button @click="emit('references')"><AppIcon name="book"/>{{tr('modules.parameter-display.methods_and_references')}}</button></template></ModuleToolbar></template>
<p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="busy" role="status">{{tr('modules.parameter-display.reading_files')}}</p>
<ModuleWorkbench unified :state-key="stateKey" :left-label="tr('modules.parameter-display.audio_files')" :right-label="tr('modules.parameter-display.plots_and_export')"><template #left><aside class="file-panel workbench-card"><label>{{tr('modules.parameter-display.audio_search')}}<input v-model="filter" :placeholder="tr('modules.parameter-display.search_audio')"/></label><div class="m02-files"><button data-audio-selection v-for="file in audios.filter(f=>f.name.toLowerCase().includes(filter.toLowerCase()))" :key="file.id" :class="{selected:file.id===selected}" :disabled="busy" @click="loadAudio(file.id)">{{file.name}}</button></div><p v-if="!audios.length" class="muted">{{tr('modules.parameter-display.upload_files_above_or_select_existing_audio')}}</p></aside></template>
<div class="signal-panel" :style="{'--m02-plot-min-width':Math.ceil(340*fontScale)+22+'px'}"><template v-if="wave.asset"><p v-if="previewNote" class="hint" role="note">{{previewNote}}</p><label>{{tr('modules.parameter-display.parameter_table_association')}}<select :value="tableId" @change="loadTable(($event.target as HTMLSelectElement).value)" :disabled="busy"><option value="">{{tr('modules.parameter-display.no_parameter_table_linked')}}</option><option v-for="file in files.filter(f=>f.kind==='parameter'||f.kind==='lip'||(f.kind==='lip_pickle'&&!/_timestamps\.pkl$/i.test(f.name)))" :key="file.id" :value="file.id">{{file.name}}</option></select></label><p v-if="!tableId" class="notice">{{tr('modules.parameter-display.no_same_name_parameter_result_was_found_you_can')}}</p>
<div ref="waveformArea" class="m02-waveform-area"><WaveformViewport compact-overview pixel-annotations spectrogram-selectable :time-axis-insets="timeAxisInsets" :track-height="130" :state="wave" :spectrogram-loader="specLoader"><template #annotations="{x,start,end,height}"><g v-if="table" class="m02-wave-annotations" pointer-events="none"><g v-for="(tier,index) in selectedTiers" :key="tier"><g v-for="run in annotationRuns(table,tier,start,end)" :key="run.start"><path :d="'M'+x(run.start)+' 0V'+height" stroke="var(--warning)" stroke-dasharray="3 4" vector-effect="non-scaling-stroke"/><text class="ipa-text" v-if="run.text&&!['sil','<sil>','eps','nan'].includes(run.text.toLowerCase())" :x="x((run.start+run.end)/2)" :y="(14+index*14)*fontScale" text-anchor="middle" fill="var(--text)" font-size="12"><title>{{tier}}</title>{{run.text}}</text></g></g></g></template></WaveformViewport></div>
<div class="m02-toolbar"><label v-if="specLoader"><input v-model="wave.showSpectrogram" type="checkbox"/>{{tr('modules.parameter-display.show_spectrogram_praat')}}</label><label>{{tr('modules.parameter-display.time_window_start_seconds')}}<input v-time-precision="'s'" type="number" min="0" :max="wave.asset.duration-wave.asset.duration/wave.zoom" step=".001" v-model.lazy.number="offsetInput" @change="syncNumberInput($event,offsetInput)"/></label><label>{{tr('modules.parameter-display.time_window_duration_seconds')}}<input v-time-precision="'s'" type="number" min=".01" :max="wave.asset.duration" step=".001" v-model.lazy.number="durationInput" @change="syncNumberInput($event,durationInput)"/></label><small>{{tr('modules.parameter-display.full_duration')}} {{wave.asset.duration.toFixed(3)}} {{tr('modules.parameter-display.s_selection')}} {{Math.abs(wave.end-wave.start).toFixed(3)}} s</small></div>
<template v-if="table"><p v-if="!groups.length" class="empty-small">{{tr('modules.parameter-display.no_plots_yet_create_one_on_the_right')}}</p><div v-for="group in groups" v-show="maximized===null||maximized===group.id" :key="group.id" :class="{'m02-maximized':maximized===group.id}"><ParameterFigure :active="target===group.id" :expanded="maximized===group.id" @activate="selectGroup(group.id)" :pending="table.streamed&&!viewReady" :table="table" :group="group" :wave="wave" :time-axis-insets="timeAxisInsets" :waveform="()=>waveformArea"><button @click="maximized=maximized===group.id?null:group.id">{{maximized===group.id?tr('modules.parameter-display.restore_plot'):tr('modules.parameter-display.enlarge_plot')}}</button><button v-if="groups.length>1&&groups[0].id!==group.id" @click="remove(group.id)">{{tr('modules.parameter-display.merge_into_first_plot')}}</button><button @click="deletePlot(group.id)">{{tr('modules.parameter-display.delete_plot')}}</button></ParameterFigure></div></template>
</template><p v-else class="empty-small">{{tr('modules.parameter-display.select_audio_to_display_its_waveform_and_parameter_plots')}}</p></div>
<template #right><aside class="parameter-summary workbench-card"><h2>{{tr('modules.parameter-display.parameters_and_plots')}}</h2><label>{{tr('modules.parameter-display.current_plot')}}<select :value="target" @change="selectGroup(Number(($event.target as HTMLSelectElement).value))" :aria-label="tr('modules.parameter-display.current_plot')" :disabled="!groups.length"><option v-if="!groups.length" :value="0">{{tr('modules.parameter-display.no_plots')}}</option><option v-for="group in groups" :key="group.id" :value="group.id">{{plotGroupTitle(group)}}</option></select></label><div class="m02-window-actions"><button @click="addGroup">{{tr('modules.parameter-display.new_plot')}}</button><button @click="deletePlot(target)" :disabled="!currentGroup">{{tr('modules.parameter-display.delete_plot')}}</button></div><p class="muted m02-current-selection" role="status">{{currentGroup?plotGroupTitle(currentGroup)+tr('modules.parameter-display.selected')+marked.length+tr('modules.parameter-display.parameters'):tr('modules.parameter-display.create_a_plot_then_select_parameters')}}</p><input v-model="search" :placeholder="tr('modules.parameter-display.search_parameters')" :aria-label="tr('modules.parameter-display.parameter_search')"/><div class="m02-toolbar"><label><input v-model="reaper" type="checkbox"/>reaper</label><label><input v-model="correction" type="checkbox"/>correction</label></div><div class="m02-toolbar m02-selection-actions"><button @click="markVisible" :disabled="!visible.length||!currentGroup||busy">{{tr('modules.parameter-display.select_all_visible_parameters')}}</button><button @click="marked=[]" :disabled="!marked.length">{{tr('modules.parameter-display.clear_selection')}}</button></div><div class="m02-parameters" :aria-label="tr('modules.parameter-display.available_parameters')"><label v-for="name in visible" :key="name" :title="name" :class="{'is-checked':marked.includes(name)}"><input v-model="marked" :value="name" :aria-label="name" type="checkbox" :disabled="!currentGroup||busy"/><span>{{name}}</span></label></div><p v-if="table&&!visible.length" class="muted">{{tr('modules.parameter-display.no_matching_parameters')}} <button @click="search='';reaper=true;correction=true">{{tr('modules.parameter-display.clear_filters')}}</button></p><p class="muted">{{tr('modules.parameter-display.click_a_plot_to_select_it_check_a_parameter')}}</p></aside></template></ModuleWorkbench></ModuleFrame></template>
<style scoped>
.m02-toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:8px 0}.m02-page{height:100%;min-height:0;overflow:auto}.m02-columns{display:grid;grid-template-columns:var(--panel-left,220px) minmax(280px,1fr) var(--panel-right,260px);gap:12px;flex:1;min-height:160px;overflow:auto}.m02-columns>aside,.m02-columns>.signal-panel{min-width:0;padding:12px;overflow:auto}.m02-columns label{display:block}.m02-columns input:not([type=checkbox]),.m02-columns select{max-width:100%;width:100%}.m02-columns>.file-panel{display:flex;flex-direction:column;min-height:0;overflow:hidden}.m02-files{display:flex;flex-direction:column;gap:4px;flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;scrollbar-gutter:stable}.m02-files button{flex:none}.recursive-option{display:flex;align-items:center;gap:4px;white-space:nowrap}.m02-files button{text-align:left;overflow-wrap:anywhere}.m02-parameters{max-height:48vh;overflow:auto}.m02-parameters label{padding:5px 0;overflow-wrap:anywhere}.parameter-summary>button{margin-top:8px;width:100%}.m02-maximized{min-width:0}.signal-panel{background:var(--panel)}@container module (max-width:720px){.m02-page{height:auto;min-height:100%;overflow:visible}.m02-columns{flex:none;overflow:visible;grid-template-columns:minmax(0,1fr)}.m02-files{max-height:170px;overflow:auto}.m02-parameters{max-height:260px}}
.m02-page .file-panel{display:flex;flex-direction:column;min-height:0;gap:8px}.m02-page .file-panel input,.m02-page .parameter-summary input:not([type=checkbox]),.m02-page .parameter-summary select{width:100%;max-width:100%}.m02-page .file-panel label{display:grid;gap:6px}.m02-page .signal-panel{padding:8px;border:1px solid var(--border);border-radius:var(--radius)}.m02-page .parameter-summary h2{font-size:1rem;margin:0 0 8px}.m02-page .parameter-summary>label{display:grid;gap:6px}.m02-page .m02-parameters{max-height:36vh}.m02-page :deep(.workbench-left>.file-panel){flex:1;min-height:0}
.m02-page .parameter-summary{display:block;container:parameter-options / inline-size}
.m02-window-actions{display:flex;gap:8px;margin:8px 0}.m02-window-actions button{flex:1;min-width:0}.m02-current-selection{margin:12px 0 8px;font-variant-numeric:tabular-nums}.m02-parameters .is-checked{color:var(--accent)}
.m02-page .m02-toolbar label{display:flex;align-items:center;gap:4px;white-space:nowrap}
.m02-page .m02-selection-actions{display:grid;gap:8px;margin:8px 0}
.m02-page .m02-selection-actions button{margin:0;width:100%}
.m02-page .m02-parameters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:2px 8px;max-height:min(28vh,260px);overflow:auto;overscroll-behavior:contain;scrollbar-gutter:stable;align-content:start}
.m02-page .m02-parameters label{display:flex;align-items:center;gap:4px;min-width:0;padding:3px 0;white-space:nowrap}
.m02-parameters input{flex:none;margin:0}
.m02-parameters span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
@container parameter-options (min-width:320px){.m02-page .m02-parameters{grid-template-columns:repeat(3,minmax(0,1fr))}}
@container parameter-options (min-width:460px){.m02-page .m02-parameters{grid-template-columns:repeat(4,minmax(0,1fr))}}
.m02-page .signal-panel{overflow-x:auto}
.m02-waveform-area{padding:0 11px;min-width:var(--m02-plot-min-width)}
.m02-page :deep(.parameter-figure){min-width:var(--m02-plot-min-width)}
.m02-waveform-area :deep(.wave-track>svg){border:0}
.m02-waveform-area :deep(.spectrogram-canvas){border:0}
</style>
